import com.google.gson.*;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

/** Public discard exchange retains one stay while revalidating both physical endpoints. */
public final class DiscardPokemonReplacementTest {
    static final UUID A=PairedTrainerPlayTest.A,B=PairedTrainerPlayTest.B;
    static void check(boolean b,String why){PairedTrainerPlayTest.check(b,why);}
    static void reject(Runnable r){PairedTrainerPlayTest.reject(r);}
    static CardInstance hand(ServerMatch m,UUID p,String id){return PairedTrainerPlayTest.hand(m,p,id);}
    static ServerMatch fixture(){var m=PairedTrainerPlayTest.fixture(PairedTrainerPlayTest.SWAP);PairedTrainerPlayTest.toDiscard(m,"high");return m;}
    static CardInstance candidate(ServerMatch m,String id){return m.effectCardPrompt(A).candidates().stream().filter(c->c.definitionId().equals(id)).findFirst().orElseThrow();}
    static void begin(ServerMatch m,UUID target){m.playTrainerPair(A,PairedTrainerPlayTest.ids(PairedTrainerPlayTest.pair(m)));var p=m.effectPokemonPrompt(A);m.chooseEffectPokemon(A,p.resolutionId(),p.step(),target);}
    static void submit(ServerMatch m,CardInstance card){var p=m.effectCardPrompt(A);m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(card.instanceId()));}
    static void swap(ServerMatch m,UUID target,String id){begin(m,target);submit(m,candidate(m,id));}
    static ProtectionEffect protection(boolean bound,String source,String from){return ProtectionEffect.from(EffectRegistry.standard().parse(JsonParser.parseString("{\"type\":\"prevent_effects\",\"target\":\"SELF\",\"source\":\""+source+"\",\"from\":\""+from+"\",\"scope\":\""+(source.equals("TRAINER")?"EFFECTS_ONLY":"DAMAGE_ONLY")+"\",\"duration\":\"OPPONENT_TURN_END\""+(bound?",\"bound_to_top_card\":true":"")+"}").getAsJsonObject()));}
    public static void main(String[] args){schemaAndPotential();candidatesAndForgery();stateAndUsage();abilityAbsentThenDifferentProgram();physicalGuards();staleHost();fossilAndOwnership();deferredKnockout();System.out.println("DiscardPokemonReplacementTest passed: strict scope, public candidates, source binding, state/usage inheritance, physical guard exception, effective Fossil, owner transfer and deferred KO");}
    static void schemaAndPotential(){
        var json=JsonParser.parseString(PairedTrainerPlayTest.REPLACE).getAsJsonObject();var atomic=EffectRegistry.standard().parse(json);
        for(var kv:Map.of("target","SELF","amount","2","minimum","0","card_category","TRAINER","basic_pokemon_only","false","preserve_state","DAMAGE_ONLY","return_old_card","HAND","source","DISCARD","bind","done","as_cost","true").entrySet()){var bad=json.deepCopy();bad.addProperty(kv.getKey(),kv.getValue());reject(()->EffectRegistry.standard().parse(bad));}
        for(var trigger:List.of(EffectTrigger.AFTER_ATTACK,EffectTrigger.ONCE_PER_TURN,EffectTrigger.ON_ACTIVATE)){var scope=EffectRegistry.standard().parse(JsonParser.parseString(PairedTrainerPlayTest.SWAP).getAsJsonObject());var program=new EffectProgram(List.of(new TriggeredEffects(trigger,List.of(),List.of(scope))));reject(()->ResumableProgramRules.validate(program,trigger!=EffectTrigger.ON_ACTIVATE,trigger));}
        var unscoped=new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.ON_CARD_PLAYED,List.of(),List.of(atomic))));reject(()->TrainerProgramRules.validate(unscoped));
        var m=PairedTrainerPlayTest.fixture(PairedTrainerPlayTest.SWAP);var pair=PairedTrainerPlayTest.ids(PairedTrainerPlayTest.pair(m));var before=m.clientView(A);check(!m.canPlayTrainerPair(A,pair),"empty public discard still playable");reject(()->m.playTrainerPair(A,pair));reject(()->m.openEffectZoneSelection(A,atomic,1));check(before.equals(m.clientView(A)),"invalid/no-op path mutated");
        PairedTrainerPlayTest.toDiscard(m,"high");var f=EventTargetBindingTest.field(m);f.addProtection(A,A,m.activePokemonView(A).pokemonId(),protection(false,"TRAINER","OWN"));for(var p:m.benchPokemonView(A))f.addProtection(A,A,p.pokemonId(),protection(false,"TRAINER","OWN"));check(!m.canPlayTrainerPair(A,pair),"protected hosts made false potential");
    }
    static void candidatesAndForgery(){var m=fixture();for(var id:List.of("evolved","restricted","fossil","small"))PairedTrainerPlayTest.toDiscard(m,id);var host=m.activePokemonView(A).pokemonId();begin(m,host);var p=m.effectCardPrompt(A);check(p.minimum()==1&&p.maximum()==1&&p.candidates().stream().map(CardInstance::definitionId).collect(java.util.stream.Collectors.toSet()).equals(Set.of("high","small")),"discard Basic/category/placement candidates wrong");var card=candidate(m,"high");var before=m.clientView(A);var random=m.randomTranscript();reject(()->m.submitEffectCards(B,p.resolutionId(),p.step(),List.of(card.instanceId())));reject(()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of()));reject(()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(card.instanceId(),card.instanceId())));var fossil=m.privateView(A).discard().stream().filter(c->c.definitionId().equals("fossil")).findFirst().orElseThrow();reject(()->submit(m,fossil));check(before.equals(m.clientView(A))&&random.equals(m.randomTranscript()),"invalid discard choice mutated");PairedTrainerPlayTest.zone(m,A,"discard").remove(card);PairedTrainerPlayTest.zone(m,A,"hand").add(card);reject(()->submit(m,card));PairedTrainerPlayTest.zone(m,A,"hand").remove(card);PairedTrainerPlayTest.zone(m,A,"discard").add(card);submit(m,card);check(m.activePokemonView(A).topCardId().equals("high"),"valid retry failed");}
    static void stateAndUsage(){var m=fixture();var f=EventTargetBindingTest.field(m);UUID host=m.activePokemonView(A).pokemonId();var original=f.topCard(A,host);long entry=f.pokemonEntrySequence(A,host);m.useAbility(A,host,"same");var energy=hand(m,A,"energy");m.attachEnergyByEffect(A,A,EffectSourceZone.HAND,energy.instanceId(),A,host);var tool=hand(m,A,"tool");m.attachToolByEffect(A,A,EffectSourceZone.HAND,tool.instanceId(),A,host);long attached=f.attachmentEntrySequence(A,host,tool.instanceId());f.placeDamageCounters(A,host,2);f.applySpecialCondition(A,SpecialCondition.POISONED);UUID marker=UUID.randomUUID();f.addDelayedMarker(A,host,marker,"replacement fixture");var before=m.activePokemonView(A);int oldReplay=m.replayTranscript().size();swap(m,host,"high");var after=m.activePokemonView(A);
        check(after.pokemonId().equals(host)&&f.pokemonEntrySequence(A,host)==entry&&after.damage()==20&&after.conditions().equals(before.conditions())&&after.attachedEnergyIds().equals(before.attachedEnergyIds())&&after.attachedTools().equals(before.attachedTools())&&f.attachmentEntrySequence(A,host,tool.instanceId())==attached&&f.hasDelayedMarker(A,host,marker),"replacement reset inherited state");check(m.privateView(A).discard().contains(original),"outgoing physical card not discarded");reject(()->m.useAbility(A,host,"same"));m.useAbility(A,host,"different");
        PairedTrainerPlayTest.toDiscard(m,"blank");swap(m,host,"blank");swap(m,host,"base");reject(()->m.useAbility(A,host,"same"));check(f.pokemonEntrySequence(A,host)==entry,"A B A reset stay");f.clearSpecialConditions(A,host,Set.of(SpecialCondition.POISONED));m.endTurn(A);m.endTurn(B);m.useAbility(A,host,"same");check(m.replayTranscript().subList(oldReplay,m.replayTranscript().size()).stream().noneMatch(e->e.operation().contains("已审核效果使宝可梦进化")),"replacement used evolution primitive");
    }
    static void abilityAbsentThenDifferentProgram(){var m=fixture();UUID host=m.activePokemonView(A).pokemonId();m.useAbility(A,host,"same");PairedTrainerPlayTest.toDiscard(m,"blank");swap(m,host,"blank");swap(m,host,"high");reject(()->m.useAbility(A,host,"same"));m.endTurn(A);m.endTurn(B);int hand=m.privateView(A).hand().size();m.useAbility(A,host,"same");check(m.privateView(A).hand().size()==hand+2,"same named Ability did not accept its server profile after absence/new turn");}
    static void physicalGuards(){for(boolean ordinary:List.of(false,true)){var m=fixture();var f=EventTargetBindingTest.field(m);UUID host=m.activePokemonView(A).pokemonId();f.addProtection(A,A,host,protection(true,"ATTACK","OPPONENT"));if(ordinary)f.addProtection(A,A,host,protection(false,"ATTACK","OPPONENT"));swap(m,host,"high");check(f.preventsImpact(A,host,new EffectOrigin(EffectOrigin.Kind.ATTACK,B,m.activePokemonView(B).pokemonId()),EffectProtection.Impact.DAMAGE)==ordinary,"physical guard transferred or ordinary equal guard lost");}}
    static void staleHost(){for(boolean reentry:List.of(false,true)){var m=fixture();var f=EventTargetBindingTest.field(m);UUID host=m.benchPokemonView(A).getFirst().pokemonId();begin(m,host);var card=candidate(m,"high");if(reentry){var left=f.removePokemonByEffect(A,host);f.placeOnBench(A,left.discardedCards().getFirst());}else{var other=hand(m,A,"blank");PairedTrainerPlayTest.zone(m,A,"hand").remove(other);var old=f.replaceTopCardByEffect(A,host,other);PairedTrainerPlayTest.zone(m,A,"discard").add(old);}var discard=List.copyOf(m.privateView(A).discard());var rng=m.randomTranscript();reject(()->submit(m,card));check(discard.equals(m.privateView(A).discard())&&rng.equals(m.randomTranscript())&&m.hasPendingCardSelection(),"stale host partially committed");m.concede(A);}}
    static void fossilAndOwnership(){var m=fixture();var fossil=hand(m,A,"fossil");m.playTrainer(A,fossil.instanceId(),null);var f=EventTargetBindingTest.field(m);UUID host=f.printedPokemonView(A,fossil.instanceId()).pokemonId();swap(m,host,"high");check(f.topCard(A,host).definitionId().equals("high")&&m.privateView(A).discard().contains(fossil),"in-play effective Basic Fossil was rejected");
        var n=fixture();var field=EventTargetBindingTest.field(n);UUID id=n.activePokemonView(A).pokemonId();var foreign=hand(n,B,"blank");PairedTrainerPlayTest.zone(n,B,"hand").remove(foreign);var own=field.replaceTopCardByEffect(A,id,foreign);PairedTrainerPlayTest.zone(n,A,"discard").add(own);swap(n,id,"high");check(n.privateView(B).discard().contains(foreign)&&!n.privateView(A).discard().contains(foreign),"outgoing card lost actual owner");
    }
    static void deferredKnockout(){var m=PairedTrainerPlayTest.fixture(PairedTrainerPlayTest.SWAP+","+PairedTrainerPlayTest.CHOICE);PairedTrainerPlayTest.toDiscard(m,"small");UUID host=m.activePokemonView(A).pokemonId();EventTargetBindingTest.field(m).placeDamageCounters(A,host,2);var cards=PairedTrainerPlayTest.pair(m);begin(m,host);submit(m,candidate(m,"small"));check(m.phase()==MatchPhase.TURN&&m.activePokemonView(A).damage()==20&&m.hasPendingEffectChoice()&&cards.stream().noneMatch(m.privateView(A).discard()::contains),"inherited lethal HP interrupted card suffix");PairedTrainerPlayTest.finishChoice(m);check(m.phase()==MatchPhase.PRIZE_SELECTION&&m.pendingChoicePlayer().equals(B)&&m.privateView(A).discard().containsAll(cards),"whole pair did not finish before KO");}
}
